const body = msg.payload || {};
const readings = Array.isArray(body.readings) ? body.readings : [];

msg.rows = readings.map((r) => ({
    timestamp: r.timestamp,
    site: body.site || '',
    device: r.device,
    metric: r.metric,
    value: r.value,
    topic: r.topic
}));

// ตอบกลับ dashboard ทันที ไม่ต้องรอเขียนไฟล์
msg.statusCode = 200;
msg.received = msg.rows.length;

node.status({ fill: 'green', shape: 'dot', text: `${msg.rows.length} rows` });

return msg;

const FILE = 'D:/CODING/Weather_Dashboard/data/sensor-readings.csv';
const HEADER = 'timestamp,site,device,metric,value,topic\r\n';

if (!msg.rows || msg.rows.length === 0) return null;

const fs = global.get('fs');
if (!fs) {
    node.error('ยังไม่ได้เปิด fs ใน functionGlobalContext ของ settings.js', msg);
    return null;
}

// เขียน BOM + header ครั้งเดียวตอนไฟล์ยังไม่มี
// BOM (\uFEFF) ทำให้ Excel บน Windows อ่าน UTF-8 ภาษาไทยได้ถูกต้อง
if (!fs.existsSync(FILE)) {
    const dir = FILE.slice(0, FILE.lastIndexOf('/'));
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(FILE, '\uFEFF' + HEADER, 'utf8');
    node.log('สร้างไฟล์ CSV ใหม่พร้อม BOM: ' + FILE);
}

msg.payload = msg.rows;
return msg;
